  "summary": "The code contained critical security vulnerabilities including LDAP injection and resource leakage. The refactored version implements proper connection management, input sanitization, and environment-based configuration to improve security and reliability.",
  "fixed_code": "import os\nfrom flask import request, Flask, jsonify\nimport ldap3\nfrom ldap3.utils.conv import escape_filter_chars\nimport re\n\napp = Flask(__name__)\n\nLDAP_SERVER = os.getenv('LDAP_SERVER', 'ldap://127.0.0.1')\nALLOWED_DC = {'example', 'corp'}\n\ndef validate_input(dc: str, username: str) -> bool:\n    return dc in ALLOWED_DC and re.match(r'^[a-zA-Z0-9_]+$', username) is not None\n\n@app.route(\"/normal\")\ndef normal() -> str:\n    unsafe_dc = request.args.get('dc', '')\n    unsafe_filter = request.args.get('username', '')\n\n    if not validate_input(unsafe_dc, unsafe_filter):\n        return jsonify({\"error\": \"Invalid input\"}), 400\n\n    dn = f\"dc={unsafe_dc}\"\n    search_filter = f\"(user={escape_filter_chars(unsafe_filter)})\"\n\n    srv = ldap3.Server(LDAP_SERVER)\n    try:\n        with ldap3.Connection(srv, user=dn, auto_bind=True) as conn:\n            result = conn.search(dn, search_filter)\n            return jsonify({\"result\": result})\n    except Exception as e:\n        return jsonify({\"error\": \"LDAP operation failed\"}), 500"
